UPDATE web_promats_products SET
  sort_order=9, name='ORBİTAL KROM SERİSİ',
  s1_1_text='ORBİTAL KROM', s1_2_text='SERİSİ', s1_3_text='Promats Orbital Krom Serisi, universal uyumluluk, dayanıklı PVC compound yapısı ve fonksiyonel yüzey tasarımıyla geliştirilen oto paspas serisidir. Dekoratif PVC film uygulaması; Karbon, Kırmızı, Mavi ve Silver olmak üzere dört farklı alternatifle sunulur. Yıkanabilir ve kesilebilir yapısıyla günlük kullanım için pratik bir çözüm sunar.',
  s1_4_image='/images/product/orbital-real-kopya.jpg', s2_1_image='/images/product/orbital-havuz.png',
  s3_1_image='/images/product/orbital-tekli.png', s3_2_image='/images/background/section7.jpg', s4_1_image='/images/product/orbital-tam-set.png',
  s2_2_text=NULL, s2_3_text='3D Konsept', s2_4_text=NULL, s2_5_text='3D form ve yükseltilmiş kenar yapısı, günlük kir ve sıvıların paspas üzerinde tutulmasına yardımcı olarak araç tabanının korunmasını destekler.',
  seo_title='ORBİTAL KROM SERİSİ | Promats', seo_description='Promats Orbital Krom Serisi, universal uyumluluk, dayanıklı PVC compound yapısı ve fonksiyonel yüzey tasarımıyla geliştirilen oto paspas serisidir. Dekoratif PVC film uygulaması; Karbon, Kırmızı, Mavi ve Silver olmak üzere dört farklı alternatifle sunulur. Yıkanabilir ve kesilebilir yapısıyla günlük',
  detail_description='<p><strong>Ürün Tipi:</strong> Universal PVC oto paspas</p><p><strong>Seri:</strong> Orbital Krom</p><p><strong>Tasarım:</strong> 3D havuzlu</p><p><strong>Set İçeriği:</strong> 5 parça</p><p><strong>Sol Ayak Dayama:</strong> Mevcut</p><p><strong>Malzeme:</strong> PVC compound</p><p><strong>Dekoratif PVC Film:</strong> Karbon, Kırmızı, Mavi, Silver</p><p><strong>Temizlik:</strong> Yıkanabilir</p><p><strong>Uyumluluk:</strong> Kesim bölgeleriyle farklı araçlara uyarlanabilir</p>', detail_technical='<ul><li>3D havuz yapısı</li><li>5 parçalı tam set</li><li>Sol ayak dayama bölümü</li><li>Modern yüzey tasarımı</li><li>Kesilebilir universal tasarım</li><li>Esnek ve dayanıklı PVC compound</li><li>Kolay temizlenebilir yüzey</li><li>Karbon, Kırmızı, Mavi ve Silver dekoratif PVC film seçenekleri</li></ul><h3>İki ön, iki arka ve bir şaft tüneli parçasından oluşan 5 parçalı set, araç tabanında geniş bir koruma alanı sağlamaya yardımcı olur. Sürücü tarafındaki sol ayak dayama bölümü de koruma alanını tamamlar.</h3><p>İki ön, iki arka ve bir şaft tüneli parçasından oluşan 5 parçalı set, ön ve arka taban alanlarıyla şaft tünelinde kapsamlı koruma sağlamaya yardımcı olur.</p>',
  detail_usage='<h3>Temizlik ve Bakım</h3><p>Paspaslar araçtan çıkarıldıktan sonra su ve uygun bir temizlik ürünüyle yıkanabilir. Yüzeydeki kirler yumuşak bir fırça veya bez yardımıyla temizlenebilir. Temizlik sonrasında paspasların tamamen kuruması beklenmeli ve ardından araca yeniden yerleştirilmelidir.</p>', detail_advantages='<h3>Orbital Krom Serisi, Orbital&#x27;in modern yüzey tasarımını sürücü tarafındaki sol ayak dayama bölümü ve dekoratif PVC film seçenekleriyle birleştirir. Ayak dayama bölümü koruma alanını genişletirken Karbon, Kırmızı, Mavi ve Silver alternatifleri ürüne farklı bir görsel karakter kazandırır.</h3><p>Orbital Serisi&#x27;nin modern yüzey deseni, dekoratif PVC film seçenekleriyle daha belirgin bir görsel karakter kazanır. Karbon, Kırmızı, Mavi ve Silver alternatifleri farklı araç içi stillerine uyum sağlar.</p><p>Orbital Krom Serisi, farklı marka ve model araçlarda kullanılabilmek üzere universal olarak geliştirilmiştir. Paspas üzerindeki belirlenmiş kesim bölgeleri, gerekli durumlarda ürünün araç tabanına göre uyarlanmasına yardımcı olur. Sürücü tarafındaki sol ayak dayama bölümü koruma alanını genişletir. Kesim öncesinde paspasın araç tabanına yerleştirilerek uyumun ve kesim ihtiyacının kontrol edilmesi önerilir.</p><h3>Premium PVC Malzeme</h3><p>Yüksek kaliteli PVC compound kullanılarak üretilir. Esnek ve dayanıklı yapısıyla uzun süreli günlük kullanıma uygundur.</p><h3>Kesilebilir Universal Tasarım</h3><p>Belirlenmiş kesim bölgeleri sayesinde farklı araç tabanlarına daha kolay uyarlanabilir.</p><h3>Kolay Temizlenebilir</h3><p>Promats Orbital Krom Serisi; Orbital modelinin 3D havuz tasarımı, modern yüzey deseni, sol ayak dayama bölümü ve 5 parçalı set yapısını dekoratif PVC film uygulamasıyla bir araya getirir. Günlük kullanımda araç tabanını su, çamur, toz ve benzeri kirleticilere karşı korumaya yardımcı olur. Sürücü tarafındaki sol ayak dayama bölümü koruma alanını genişletir. Karbon, Kırmızı, Mavi ve Silver film alternatifleri farklı görsel tercihlere seçenek sunar.</p><h3>Sık Sorulan Sorular</h3><p>Orbital Krom hangi araçlara uyar?</p><p>Universal yapısı sayesinde birçok binek otomobil ve uygun taban ölçülerine sahip farklı araçlarda kullanılabilir.</p><p>Orbital Krom kesilebilir mi?</p><p>Evet. Belirlenmiş kesim bölgeleri, gerekli durumlarda paspasın araç tabanına göre uyarlanmasına yardımcı olur.</p><p>Orbital Krom kaç parçadır?</p><p>Set; iki ön, iki arka ve bir şaft tüneli parçası olmak üzere toplam 5 parçadan oluşur.</p><p>Sol ayak dayama bölümü var mı?</p><p>Hayır. Bu modelde sürücü tarafında ilave sol ayak dayama bölümü bulunmaz.</p><p>Orbital Krom havuzlu mudur?</p><p>Evet. Havuzlu yapısı günlük kir ve sıvıların paspas üzerinde tutulmasına yardımcı olur.</p><p>Krom/dekoratif film seçenekleri nelerdir?</p><p>Karbon, Kırmızı, Mavi ve Silver olmak üzere dört farklı PVC film alternatifi sunulur.</p><p>Orbital Krom hangi malzemeden üretilir?</p><p>PVC compound kullanılarak üretilir.</p><p>Orbital Krom nasıl temizlenir?</p><p>Araçtan çıkarılarak su ve uygun bir temizlik ürünüyle kolayca temizlenebilir.</p><h3>Orbital Krom Serisi Hakkında Bilgi Alın</h3><p>Orbital Krom Serisi ürün özellikleri, fiyat bilgisi veya satış koşulları hakkında detaylı bilgi almak için bizimle iletişime geçebilirsiniz.</p>',
  detail_material='<p>Orbital Krom Serisi, Promats&#x27;ın PVC compound üretim yaklaşımıyla üretilir. Malzeme yapısında esneklik, formunu koruma, günlük kullanıma karşı dayanıklılık ve düşük koku hedeflenir. Dekoratif PVC film uygulaması; Karbon, Kırmızı, Mavi ve Silver olmak üzere dört farklı alternatifle sunulur.</p>', detail_universal='<p>Orbital Krom Serisi, farklı marka ve model araçlarda kullanılabilmek üzere universal olarak geliştirilmiştir. Paspas üzerindeki belirlenmiş kesim bölgeleri, gerekli durumlarda ürünün araç tabanına göre uyarlanmasına yardımcı olur. Kesim öncesinde paspasın araç tabanına yerleştirilerek uyumun ve kesim ihtiyacının kontrol edilmesi önerilir.</p>', status=1
WHERE id=@product_id;
