UPDATE web_promats_products SET
  sort_order=10, name='KAPİTONE SERİSİ',
  s1_1_text='KAPİTONE', s1_2_text='SERİSİ', s1_3_text='Promats Kapitone Serisi, universal uyumluluk, dayanıklı PVC compound yapısı ve fonksiyonel yüzey tasarımıyla geliştirilen oto paspas serisidir. Yıkanabilir ve kesilebilir yapısıyla günlük kullanım için pratik bir çözüm sunar.',
  s1_4_image='/userfiles/images/product/catalog-2026/kapitone-serisi/cover.jpg', s2_1_image='/userfiles/images/product/catalog-2026/kapitone-serisi/concept.png',
  s3_1_image='/userfiles/images/product/catalog-2026/kapitone-serisi/detail.png', s3_2_image='/images/background/section7.jpg', s4_1_image='/userfiles/images/product/catalog-2026/kapitone-serisi/set.png',
  s2_2_text=NULL, s2_3_text='Universal Uyum ve Fonksiyonel Tasarım', s2_4_text=NULL, s2_5_text='Havuzsuz ve esnek universal yapı, günlük kullanımda araç tabanını kir, toz ve neme karşı korumaya yardımcı olur; farklı araç tabanlarına uyarlanabilir.',
  seo_title='KAPİTONE SERİSİ | Promats', seo_description='Promats Kapitone Serisi, universal uyumluluk, dayanıklı PVC compound yapısı ve fonksiyonel yüzey tasarımıyla geliştirilen oto paspas serisidir. Yıkanabilir ve kesilebilir yapısıyla günlük kullanım için pratik bir çözüm sunar.',
  detail_description='<p>Promats Kapitone Serisi; düz / havuzsuz universal tasarım, 5 parçalı set yapısı ve dayanıklı PVC compound malzemeyi bir araya getiren universal oto paspas serisidir. Günlük kullanımda araç tabanını kir, toz, nem ve kullanım koşullarına bağlı kirleticilere karşı korumaya yardımcı olur. Kesilebilir universal yapısı farklı araç tabanlarına uyarlama imkânı sunarken, yıkanabilir yüzeyi bakım ve temizliği kolaylaştırır.</p>', detail_technical='<p><strong>Ürün Tipi:</strong> Universal PVC oto paspas</p><p><strong>Seri:</strong> Kapitone</p><p><strong>Tasarım:</strong> Düz / havuzsuz universal tasarım</p><p><strong>Set İçeriği:</strong> 5 parça</p><p><strong>Sol Ayak Dayama:</strong> Yok</p><p><strong>Malzeme:</strong> PVC compound</p><p><strong>Renk / Dekor Seçenekleri:</strong> Standart PVC renk seçenekleri</p><p><strong>Temizlik:</strong> Yıkanabilir</p><p><strong>Uyumluluk:</strong> Kesim bölgeleriyle farklı araçlara uyarlanabilir</p><h3>5 Parça Tam Set</h3><p>İki ön, iki arka ve bir şaft tüneli parçasından oluşan 5 parçalı set, ön ve arka taban alanlarıyla şaft tünelinde kapsamlı koruma sağlamaya yardımcı olur.</p>',
  detail_usage='<h3>Temizlik ve Bakım</h3><p>Paspaslar araçtan çıkarıldıktan sonra su ve uygun bir temizlik ürünüyle yıkanabilir. Yüzeydeki kirler yumuşak bir fırça veya bez yardımıyla temizlenebilir. Temizlik sonrasında paspasların tamamen kuruması beklenmeli ve ardından araca yeniden yerleştirilmelidir.</p>', detail_advantages='<h3>Kapitone Desenli Yüzey</h3><p>Kapitone Serisi, yüzeyindeki karakteristik kapitone desenle klasik ve dikkat çekici bir görünüm sunar; universal yapısıyla günlük kullanım için pratik bir çözüm oluşturur.</p><ul><li>Havuzsuz universal tasarım</li><li>5 parçalı tam set</li><li>Kapitone Desenli Yüzey</li><li>Kesilebilir universal tasarım</li><li>Esnek ve dayanıklı PVC compound</li><li>Kolay temizlenebilir yüzey</li></ul><h3>Premium PVC Malzeme</h3><p>Yüksek kaliteli PVC compound kullanılarak üretilir. Esnek ve dayanıklı yapısıyla uzun süreli günlük kullanıma uygundur.</p><h3>Kesilebilir Universal Tasarım</h3><p>Belirlenmiş kesim bölgeleri sayesinde farklı araç tabanlarına daha kolay uyarlanabilir.</p><h3>Kolay Temizlenebilir</h3><p>Yıkanabilir PVC yüzeyi sayesinde su, toz ve günlük kirler kolayca temizlenebilir.</p><h3>Sık Sorulan Sorular</h3><p>Kapitone hangi araçlara uyar?</p><p>Universal yapısı sayesinde birçok binek otomobil ve uygun taban ölçülerine sahip farklı araçlarda kullanılabilir.</p><p>Kapitone kesilebilir mi?</p><p>Evet. Belirlenmiş kesim bölgeleri, gerekli durumlarda paspasın araç tabanına göre uyarlanmasına yardımcı olur.</p><p>Kapitone kaç parçadır?</p><p>Set; iki ön, iki arka ve bir şaft tüneli parçası olmak üzere toplam 5 parçadan oluşur.</p><p>Sol ayak dayama bölümü var mı?</p><p>Hayır. Bu modelde sürücü tarafında ilave sol ayak dayama bölümü bulunmaz.</p><p>Kapitone havuzlu veya 3D bir paspas mıdır?</p><p>Hayır. Bu model havuzsuz universal PVC oto paspas yapısındadır.</p><p>Kapitone hangi malzemeden üretilir?</p><p>PVC compound kullanılarak üretilir.</p><p>Kapitone nasıl temizlenir?</p><p>Araçtan çıkarılarak su ve uygun bir temizlik ürünüyle kolayca temizlenebilir.</p><h3>Kapitone Serisi Hakkında Bilgi Alın</h3><p>Kapitone Serisi ürün özellikleri, fiyat bilgisi veya satış koşulları hakkında detaylı bilgi almak için bizimle iletişime geçebilirsiniz.</p>',
  detail_material='<p>Kapitone Serisi, Promats&#x27;ın PVC compound üretim yaklaşımıyla üretilir. Malzeme yapısında esneklik, formunu koruma, günlük kullanıma karşı dayanıklılık ve düşük koku hedeflenir.</p>', detail_universal='<p>Kapitone Serisi, farklı marka ve model araçlarda kullanılabilmek üzere universal olarak geliştirilmiştir. Paspas üzerindeki belirlenmiş kesim bölgeleri, gerekli durumlarda ürünün araç tabanına göre uyarlanmasına yardımcı olur. Kesim öncesinde paspasın araç tabanına yerleştirilerek uyumun ve kesim ihtiyacının kontrol edilmesi önerilir.</p>', status=1
