UPDATE web_promats_products SET
  sort_order=20, name='YENİ NESİL KROM SERİSİ',
  s1_1_text='YENİ NESİL KROM', s1_2_text='SERİSİ', s1_3_text='Promats Yeni Nesil Krom Serisi, universal uyumluluk, dayanıklı PVC compound yapısı ve fonksiyonel yüzey tasarımıyla geliştirilen oto paspas serisidir. Dekoratif PVC film uygulaması; Karbon, Kırmızı, Mavi ve Silver olmak üzere dört farklı alternatifle sunulur. Yıkanabilir ve kesilebilir yapısıyla günlük kullanım için pratik bir çözüm sunar.',
  s1_4_image='/userfiles/images/product/catalog-2026/yeni-nesil-krom-serisi/cover.jpg', s2_1_image='/userfiles/images/product/catalog-2026/yeni-nesil-krom-serisi/concept.png',
  s3_1_image='/userfiles/images/product/catalog-2026/yeni-nesil-krom-serisi/detail.png', s3_2_image='/images/background/section7.jpg', s4_1_image='/userfiles/images/product/catalog-2026/yeni-nesil-krom-serisi/set.png',
  s2_2_text=NULL, s2_3_text='Universal Uyum ve Fonksiyonel Tasarım', s2_4_text=NULL, s2_5_text='Havuzsuz ve esnek universal yapı, günlük kullanımda araç tabanını kir, toz ve neme karşı korumaya yardımcı olur; farklı araç tabanlarına uyarlanabilir.',
  seo_title='YENİ NESİL KROM SERİSİ | Promats', seo_description='Promats Yeni Nesil Krom Serisi, universal uyumluluk, dayanıklı PVC compound yapısı ve fonksiyonel yüzey tasarımıyla geliştirilen oto paspas serisidir. Dekoratif PVC film uygulaması; Karbon, Kırmızı, Mavi ve Silver olmak üzere dört farklı alternatifle sunulur. Yıkanabilir ve kesilebilir yapısıyla gün',
  detail_description='<p>Promats Yeni Nesil Krom Serisi; düz / havuzsuz universal tasarım, 5 parçalı set yapısı ve dayanıklı PVC compound malzemeyi bir araya getiren universal oto paspas serisidir. Günlük kullanımda araç tabanını kir, toz, nem ve kullanım koşullarına bağlı kirleticilere karşı korumaya yardımcı olur. Dekoratif PVC film uygulaması; Karbon, Kırmızı, Mavi ve Silver olmak üzere dört farklı alternatifle sunulur. Kesilebilir universal yapısı farklı araç tabanlarına uyarlama imkânı sunarken, yıkanabilir yüzeyi bakım ve temizliği kolaylaştırır.</p>', detail_technical='<p><strong>Ürün Tipi:</strong> Universal PVC oto paspas</p><p><strong>Seri:</strong> Yeni Nesil Krom</p><p><strong>Tasarım:</strong> Düz / havuzsuz universal tasarım</p><p><strong>Set İçeriği:</strong> 5 parça</p><p><strong>Sol Ayak Dayama:</strong> Yok</p><p><strong>Malzeme:</strong> PVC compound</p><p><strong>Renk / Dekor Seçenekleri:</strong> Karbon, Kırmızı, Mavi, Silver</p><p><strong>Temizlik:</strong> Yıkanabilir</p><p><strong>Uyumluluk:</strong> Kesim bölgeleriyle farklı araçlara uyarlanabilir</p><p><strong>Dekoratif PVC Film:</strong> Karbon, Kırmızı, Mavi, Silver</p><h3>5 Parça Tam Set</h3><p>İki ön, iki arka ve bir şaft tüneli parçasından oluşan 5 parçalı set, ön ve arka taban alanlarıyla şaft tünelinde kapsamlı koruma sağlamaya yardımcı olur.</p>',
  detail_usage='<h3>Temizlik ve Bakım</h3><p>Paspaslar araçtan çıkarıldıktan sonra su ve uygun bir temizlik ürünüyle yıkanabilir. Yüzeydeki kirler yumuşak bir fırça veya bez yardımıyla temizlenebilir. Temizlik sonrasında paspasların tamamen kuruması beklenmeli ve ardından araca yeniden yerleştirilmelidir.</p>', detail_advantages='<h3>Yeni Nesil Tasarım ve Dekoratif Film</h3><p>Yeni Nesil Krom, havuzsuz Yeni Nesil modelin temel özelliklerini korurken Karbon, Kırmızı, Mavi ve Silver dekoratif PVC film alternatifleriyle daha belirgin bir görsel karakter sunar.</p><ul><li>Havuzsuz universal tasarım</li><li>5 parçalı tam set</li><li>Yeni Nesil Tasarım ve Dekoratif Film</li><li>Kesilebilir universal tasarım</li><li>Esnek ve dayanıklı PVC compound</li><li>Kolay temizlenebilir yüzey</li><li>4 farklı dekoratif PVC film seçeneği</li></ul><h3>Premium PVC Malzeme</h3><p>Yüksek kaliteli PVC compound kullanılarak üretilir. Esnek ve dayanıklı yapısıyla uzun süreli günlük kullanıma uygundur.</p><h3>Kesilebilir Universal Tasarım</h3><p>Belirlenmiş kesim bölgeleri sayesinde farklı araç tabanlarına daha kolay uyarlanabilir.</p><h3>Kolay Temizlenebilir</h3><p>Yıkanabilir PVC yüzeyi sayesinde su, toz ve günlük kirler kolayca temizlenebilir.</p><h3>Sık Sorulan Sorular</h3><p>Yeni Nesil Krom hangi araçlara uyar?</p><p>Universal yapısı sayesinde birçok binek otomobil ve uygun taban ölçülerine sahip farklı araçlarda kullanılabilir.</p><p>Yeni Nesil Krom kesilebilir mi?</p><p>Evet. Belirlenmiş kesim bölgeleri, gerekli durumlarda paspasın araç tabanına göre uyarlanmasına yardımcı olur.</p><p>Yeni Nesil Krom kaç parçadır?</p><p>Set; iki ön, iki arka ve bir şaft tüneli parçası olmak üzere toplam 5 parçadan oluşur.</p><p>Sol ayak dayama bölümü var mı?</p><p>Hayır. Bu modelde sürücü tarafında ilave sol ayak dayama bölümü bulunmaz.</p><p>Yeni Nesil Krom havuzlu veya 3D bir paspas mıdır?</p><p>Hayır. Bu model havuzsuz universal PVC oto paspas yapısındadır.</p><p>Krom/dekoratif film seçenekleri nelerdir?</p><p>Karbon, Kırmızı, Mavi ve Silver olmak üzere dört farklı PVC film alternatifi sunulur.</p><p>Yeni Nesil Krom hangi malzemeden üretilir?</p><p>PVC compound kullanılarak üretilir.</p><p>Yeni Nesil Krom nasıl temizlenir?</p><p>Araçtan çıkarılarak su ve uygun bir temizlik ürünüyle kolayca temizlenebilir.</p><h3>Yeni Nesil Krom Serisi Hakkında Bilgi Alın</h3><p>Yeni Nesil Krom Serisi ürün özellikleri, fiyat bilgisi veya satış koşulları hakkında detaylı bilgi almak için bizimle iletişime geçebilirsiniz.</p>',
  detail_material='<p>Yeni Nesil Krom Serisi, Promats&#x27;ın PVC compound üretim yaklaşımıyla üretilir. Malzeme yapısında esneklik, formunu koruma, günlük kullanıma karşı dayanıklılık ve düşük koku hedeflenir. Dekoratif PVC film uygulaması; Karbon, Kırmızı, Mavi ve Silver olmak üzere dört farklı alternatifle sunulur.</p>', detail_universal='<p>Yeni Nesil Krom Serisi, farklı marka ve model araçlarda kullanılabilmek üzere universal olarak geliştirilmiştir. Paspas üzerindeki belirlenmiş kesim bölgeleri, gerekli durumlarda ürünün araç tabanına göre uyarlanmasına yardımcı olur. Kesim öncesinde paspasın araç tabanına yerleştirilerek uyumun ve kesim ihtiyacının kontrol edilmesi önerilir.</p>', status=1
